   441→// runCmd executes a command, logs stdout/stderr line-by-line, and returns an
   442→// error on non-zero exit.
   443→func runCmd(ctx context.Context, logger *slog.Logger, dir string, name string, args ...string) error {
   444→	cmd := exec.CommandContext(ctx, name, args...)
   445→	if dir != "" {
   446→		cmd.Dir = dir
   447→	}
   448→
   449→	var stdout, stderr bytes.Buffer
   450→	cmd.Stdout = &stdout
   451→	cmd.Stderr = &stderr
   452→
   453→	start := time.Now()
   454→	runErr := cmd.Run()
   455→	dur := time.Since(start).Round(time.Millisecond)
   456→
   457→	logLines := func(output string, level slog.Level) {
   458→		for line := range strings.Lines(output) {
   459→			line = strings.TrimRight(line, "\n\r")
   460→			if line != "" {
   461→				logger.Log(ctx, level, line, "cmd", name)
   462→			}
   463→		}
   464→	}
   465→
   466→	logLines(stdout.String(), slog.LevelInfo)
   467→	if stderr.Len() > 0 {
   468→		logLines(stderr.String(), slog.LevelWarn)
   469→	}
   470→
   471→	if runErr != nil {
   472→		return fmt.Errorf("%s: %w (duration: %s)", name, runErr, dur)
   473→	}
   474→
   475→	logger.Info("command completed", "cmd", name, "duration", dur)
   476→	return nil
   477→}
