   176→// RunUpdateScript executes the stack's update script with the required environment.
   177→func (m *StackManager) RunUpdateScript(ctx context.Context, stackName string) error {
   178→	stack, ok := m.Config.Stacks[stackName]
   179→	if !ok {
   180→		return fmt.Errorf("stack %q not found in config", stackName)
   181→	}
   182→	if stack.UpdateScript == "" {
   183→		return fmt.Errorf("stack %q has no update_script configured", stackName)
   184→	}
   185→
   186→	scriptPath := filepath.Join(m.repoDir(), stack.UpdateScript)
   187→	deployDir := m.stackDeployDir(stackName)
   188→	repoLink := filepath.Join(deployDir, "repo")
   189→
   190→	composeName, _ := findComposeFile(repoLink)
   191→	if composeName == "" {
   192→		composeName = "compose.yaml"
   193→	}
   194→	composeFile := filepath.Join(repoLink, composeName)
   195→
   196→	env := append(os.Environ(),
   197→		"STACK_NAME="+stackName,
   198→		"STACK_DIR="+deployDir,
   199→		"STACK_DOMAIN="+stack.Domain,
   200→		"COMPOSE_FILE="+composeFile,
   201→	)
   202→
   203→	m.Logger.Info("running update script", "stack", stackName, "script", scriptPath, "dir", deployDir)
   204→
   205→	cmd := exec.CommandContext(ctx, "/bin/bash", "-euo", "pipefail", scriptPath)
   206→	cmd.Dir = deployDir
   207→	cmd.Env = env
   208→
   209→	ring := newRingBuffer(50)
   210→	outWriter := &lineWriter{logger: m.Logger, cmd: "update-script[" + stackName + "]", level: slog.LevelInfo, ring: ring}
   211→	errWriter := &lineWriter{logger: m.Logger, cmd: "update-script[" + stackName + "]", level: slog.LevelWarn, ring: ring}
   212→	cmd.Stdout = outWriter
   213→	cmd.Stderr = errWriter
   214→
   215→	start := time.Now()
   216→	runErr := cmd.Run()
   217→	outWriter.flush()
   218→	errWriter.flush()
   219→	dur := time.Since(start).Round(time.Millisecond)
   220→
   221→	if runErr != nil {
   222→		exitCode := -1
   223→		if exitErr, ok := runErr.(*exec.ExitError); ok {
   224→			exitCode = exitErr.ExitCode()
   225→		}
   226→		lastLines := strings.Join(ring.get(), "\n")
   227→		return fmt.Errorf("update script exited with code %d (duration: %s):\n%s", exitCode, dur, lastLines)
   228→	}
   229→
   230→	m.Logger.Info("update script completed", "stack", stackName, "duration", dur)
   231→	return nil
   232→}
