   282→// --- Compose override generation ---
   283→
   284→type composeOverride struct {
   285→	Services map[string]serviceOverride `yaml:"services"`
   286→	Networks map[string]networkDef      `yaml:"networks,omitempty"`
   287→}
   288→
   289→type serviceOverride struct {
   290→	Labels   map[string]string `yaml:"labels,omitempty"`
   291→	Networks []string          `yaml:"networks,omitempty"`
   292→}
   293→
   294→type networkDef struct {
   295→	External bool `yaml:"external"`
   296→}
   297→
   298→type minimalCompose struct {
   299→	Services map[string]minimalService `yaml:"services"`
   300→}
   301→
   302→type minimalService struct {
   303→	Expose []any `yaml:"expose"`
   304→	Ports  []any `yaml:"ports"`
   305→}
   306→
   307→func (m *StackManager) generateOverride(deployDir, stackName string, stack config.Stack, composeFile string) error {
   308→	serviceName, port, err := detectServiceInfo(composeFile, stackName)
   309→	if err != nil {
   310→		m.Logger.Warn("could not detect service info, using defaults", "stack", stackName, "error", err)
   311→		serviceName = "app"
   312→		port = "80"
   313→	}
   314→
   315→	override := composeOverride{
   316→		Services: map[string]serviceOverride{
   317→			serviceName: {
   318→				Labels: map[string]string{
   319→					"caddy":               stack.Domain,
   320→					"caddy.reverse_proxy": fmt.Sprintf("{{upstreams %s}}", port),
   321→				},
   322→				Networks: []string{"caddy"},
   323→			},
   324→		},
   325→		Networks: map[string]networkDef{
   326→			"caddy": {External: true},
   327→		},
   328→	}
   329→
   330→	data, err := yaml.Marshal(override)
   331→	if err != nil {
   332→		return fmt.Errorf("marshaling compose override: %w", err)
   333→	}
   334→
   335→	return os.WriteFile(filepath.Join(deployDir, "compose.override.yml"), data, 0644)
   336→}
   337→
   338→func detectServiceInfo(composeFilePath, stackName string) (serviceName, port string, err error) {
   339→	data, err := os.ReadFile(composeFilePath)
   340→	if err != nil {
   341→		return "", "", err
   342→	}
   343→
   344→	var mc minimalCompose
   345→	if err := yaml.Unmarshal(data, &mc); err != nil {
   346→		return "", "", err
   347→	}
   348→
   349→	if len(mc.Services) == 0 {
   350→		return "app", "80", nil
   351→	}
   352→
   353→	names := slices.Sorted(maps.Keys(mc.Services))
   354→	serviceName = names[0]
   355→	for _, n := range names {
   356→		if n == "app" || n == stackName {
   357→			serviceName = n
   358→			break
   359→		}
   360→	}
   361→
   362→	port = extractFirstPort(mc.Services[serviceName])
   363→	if port == "" {
   364→		port = "80"
   365→	}
   366→	return serviceName, port, nil
   367→}
   368→
   369→func extractFirstPort(svc minimalService) string {
   370→	for _, v := range svc.Expose {
   371→		if p := portFromAny(v); p != "" {
   372→			return p
   373→		}
   374→	}
   375→	for _, v := range svc.Ports {
   376→		if p := portFromAny(v); p != "" {
   377→			return p
   378→		}
   379→	}
   380→	return ""
   381→}
   382→
   383→func portFromAny(v any) string {
   384→	switch val := v.(type) {
   385→	case string:
   386→		parts := strings.Split(val, ":")
   387→		return strings.TrimSpace(parts[len(parts)-1])
   388→	case int:
   389→		return fmt.Sprintf("%d", val)
   390→	case map[string]any:
   391→		if t, ok := val["target"]; ok {
   392→			return portFromAny(t)
   393→		}
   394→	}
   395→	return ""
   396→}
