   270→func runCmd(ctx context.Context, logger *slog.Logger, name string, args ...string) error {
   271→	cmd := exec.CommandContext(ctx, name, args...)
   272→	var stdout, stderr bytes.Buffer
   273→	cmd.Stdout = &stdout
   274→	cmd.Stderr = &stderr
   275→
   276→	runErr := cmd.Run()
   277→
   278→	for line := range strings.Lines(stdout.String()) {
   279→		line = strings.TrimRight(line, "\n\r")
   280→		if line != "" {
   281→			logger.Info(line, "cmd", name)
   282→		}
   283→	}
   284→	if stderr.Len() > 0 {
   285→		for line := range strings.Lines(stderr.String()) {
   286→			line = strings.TrimRight(line, "\n\r")
   287→			if line != "" {
   288→				logger.Warn(line, "cmd", name)
   289→			}
   290→		}
   291→	}
   292→	if runErr != nil {
   293→		stderrStr := strings.TrimSpace(stderr.String())
   294→		if stderrStr != "" {
   295→			return fmt.Errorf("%s: %w: %s", name, runErr, stderrStr)
   296→		}
   297→		return fmt.Errorf("%s: %w", name, runErr)
   298→	}
   299→	return nil
   300→}
   301→
   302→func runCmdOutput(ctx context.Context, name string, args ...string) (string, error) {
   303→	cmd := exec.CommandContext(ctx, name, args...)
   304→	out, err := cmd.Output()
   305→	if err != nil {
   306→		return "", fmt.Errorf("%s: %w", name, err)
   307→	}
   308→	return string(out), nil
   309→}
