   258→// splitRepo splits "owner/repo" into its two components.
   259→func splitRepo(fullRepo string) (string, string, error) {
   260→	parts := strings.SplitN(fullRepo, "/", 2)
   261→	if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
   262→		return "", "", fmt.Errorf("invalid repo format %q, expected owner/repo", fullRepo)
   263→	}
   264→	return parts[0], parts[1], nil
   265→}
