   267→// webhookURL returns the herald webhook URL derived from config.
   268→func webhookURL(cfg *config.Config) string {
   269→	return "https://" + cfg.Server.DeployDomain + "/webhook"
   270→}
   271→
   272→// eventsForRepo returns the events to subscribe to for a repo.
   273→// Subscribes to pull_request if any app referencing the repo has preview enabled.
   274→func eventsForRepo(cfg *config.Config, repo string) []string {
   275→	for _, app := range cfg.Apps {
   276→		if app.Repo == repo && app.Preview != nil && app.Preview.Enabled {
   277→			return []string{"push", "pull_request"}
   278→		}
   279→	}
   280→	return []string{"push"}
   281→}
