   283→// formatAPIError wraps a GitHub API error with actionable messaging.
   284→func formatAPIError(repo string, err error) error {
   285→	var ghErr *GitHubError
   286→	if errors.As(err, &ghErr) && ghErr.StatusCode == http.StatusNotFound {
   287→		return fmt.Errorf("cannot manage webhooks for %q: ensure the token has 'admin:repo_hook' scope and access to this repository", repo)
   288→	}
   289→	return err
   290→}
