    35→// SubdomainFromBranch derives the preview subdomain for a branch name.
    36→// The previewDomain must contain a wildcard, e.g. "*.preview.basalt.solutions".
    37→func SubdomainFromBranch(branch, previewDomain string) string {
    38→	return strings.Replace(previewDomain, "*", branchSlug(branch), 1)
    39→}
    40→
    41→// branchSlug converts a branch name into a DNS-safe label (max 63 chars).
    42→func branchSlug(branch string) string {
    43→	branch = strings.TrimPrefix(branch, "refs/heads/")
    44→
    45→	// Join path segments with "-" using iterator pattern.
    46→	var parts []string
    47→	for part := range strings.SplitSeq(branch, "/") {
    48→		if part != "" {
    49→			parts = append(parts, part)
    50→		}
    51→	}
    52→	branch = strings.Join(parts, "-")
    53→
    54→	// Replace non-alphanumeric (except "-") with "-".
    55→	var b strings.Builder
    56→	for _, r := range branch {
    57→		switch {
    58→		case r >= 'a' && r <= 'z', r >= 'A' && r <= 'Z', r >= '0' && r <= '9', r == '-':
    59→			b.WriteRune(r)
    60→		default:
    61→			b.WriteRune('-')
    62→		}
    63→	}
    64→
    65→	slug := strings.ToLower(b.String())
    66→	if len(slug) > 63 {
    67→		slug = slug[:63]
    68→	}
    69→	return strings.Trim(slug, "-")
    70→}
    71→
    72→// makeID generates a preview ID from the app name and branch.
    73→func makeID(appName, branch string) string {
    74→	return appName + "-" + branchSlug(branch)
    75→}
