    77→// Deploy creates or updates a preview for the given app and branch.
    78→func (m *PreviewManager) Deploy(ctx context.Context, appName, branch, commit string) error {
    79→	app, ok := m.Config.Apps[appName]
    80→	if !ok {
    81→		return fmt.Errorf("app %q not found in config", appName)
    82→	}
    83→	if app.Preview == nil || !app.Preview.Enabled {
    84→		return fmt.Errorf("app %q does not have preview enabled", appName)
    85→	}
    86→
    87→	id := makeID(appName, branch)
    88→	domain := SubdomainFromBranch(branch, app.Preview.Domain)
    89→	previewDir := m.previewDir(id)
    90→	composeProject := "herald-preview-" + id
    91→
    92→	m.mu.Lock()
    93→	state, err := loadState(statePath(m.DataDir))
    94→	if err != nil {
    95→		m.mu.Unlock()
    96→		return fmt.Errorf("loading state: %w", err)
    97→	}
    98→
    99→	// Count existing previews for this app (excluding an update to this id).
   100→	existingCount := 0
   101→	isUpdate := false
   102→	for _, p := range state.Previews {
   103→		if p.AppName == appName {
   104→			if p.ID == id {
   105→				isUpdate = true
   106→			} else {
   107→				existingCount++
   108→			}
   109→		}
   110→	}
   111→	m.mu.Unlock()
   112→
   113→	if !isUpdate && existingCount >= maxPreviewsPerApp {
   114→		return fmt.Errorf("max previews (%d) reached for app %q", maxPreviewsPerApp, appName)
   115→	}
   116→
   117→	m.Logger.Info("preview deploy started", "id", id, "domain", domain)
   118→	start := time.Now()
   119→
   120→	if err := os.MkdirAll(previewDir, 0755); err != nil {
   121→		return fmt.Errorf("creating preview dir: %w", err)
   122→	}
   123→
   124→	if err := m.gitSync(ctx, previewDir, app, branch); err != nil {
   125→		return fmt.Errorf("git: %w", err)
   126→	}
   127→
   128→	envVars, dockerSecrets, err := m.Secrets.Resolve(app.Secrets)
   129→	if err != nil {
   130→		return fmt.Errorf("resolving secrets: %w", err)
   131→	}
   132→
   133→	previewRoot, err := os.OpenRoot(previewDir)
   134→	if err != nil {
   135→		return fmt.Errorf("opening preview root: %w", err)
   136→	}
   137→	defer previewRoot.Close()
   138→
   139→	if err := writeEnvFile(previewRoot, envVars); err != nil {
   140→		return fmt.Errorf("writing .env: %w", err)
   141→	}
   142→
   143→	if len(dockerSecrets) > 0 {
   144→		secretsDir := filepath.Join(previewDir, "secrets")
   145→		if err := os.MkdirAll(secretsDir, 0700); err != nil {
   146→			return fmt.Errorf("creating secrets dir: %w", err)
   147→		}
   148→		secretsRoot, err := previewRoot.OpenRoot("secrets")
   149→		if err != nil {
   150→			return fmt.Errorf("opening secrets root: %w", err)
   151→		}
   152→		defer secretsRoot.Close()
   153→		for name, val := range dockerSecrets {
   154→			if err := writeSecret(secretsRoot, name, val); err != nil {
   155→				return fmt.Errorf("writing secret %q: %w", name, err)
   156→			}
   157→		}
   158→	}
   159→
   160→	repoDir := filepath.Join(previewDir, "repo")
   161→	if err := m.generateOverride(previewRoot, previewDir, appName, id, domain, app, repoDir, dockerSecrets); err != nil {
   162→		return fmt.Errorf("generating override: %w", err)
   163→	}
   164→
   165→	if err := ensureCaddyNetwork(ctx, m.Logger); err != nil {
   166→		return fmt.Errorf("ensuring caddy network: %w", err)
   167→	}
   168→
   169→	if err := m.runCompose(ctx, previewDir, composeProject, app.Compose); err != nil {
   170→		return fmt.Errorf("compose: %w", err)
   171→	}
   172→
   173→	m.mu.Lock()
   174→	defer m.mu.Unlock()
   175→
   176→	state, err = loadState(statePath(m.DataDir))
   177→	if err != nil {
   178→		return fmt.Errorf("reloading state: %w", err)
   179→	}
   180→
   181→	if isUpdate {
   182→		for i, p := range state.Previews {
   183→			if p.ID == id {
   184→				state.Previews[i].Commit = commit
   185→				break
   186→			}
   187→		}
   188→	} else {
   189→		state.Previews = append(state.Previews, PreviewInfo{
   190→			ID:             id,
   191→			AppName:        appName,
   192→			Branch:         branch,
   193→			Domain:         domain,
   194→			Directory:      previewDir,
   195→			ComposeProject: composeProject,
   196→			ComposeFile:    app.Compose,
   197→			CreatedAt:      time.Now().UTC(),
   198→			Commit:         commit,
   199→		})
   200→	}
   201→
   202→	if err := saveState(statePath(m.DataDir), state); err != nil {
   203→		return fmt.Errorf("saving state: %w", err)
   204→	}
   205→
   206→	m.Logger.Info("preview deployed", "id", id, "domain", domain, "duration", time.Since(start).Round(time.Millisecond))
   207→	return nil
   208→}
