   280→// Cleanup removes previews whose branches no longer exist on the remote.
   281→func (m *PreviewManager) Cleanup(ctx context.Context) error {
   282→	m.mu.Lock()
   283→	state, err := loadState(statePath(m.DataDir))
   284→	m.mu.Unlock()
   285→	if err != nil {
   286→		return err
   287→	}
   288→
   289→	var removed []string
   290→	for _, p := range state.Previews {
   291→		app, ok := m.Config.Apps[p.AppName]
   292→		if !ok {
   293→			m.Logger.Warn("preview references unknown app, removing", "id", p.ID)
   294→			if err := m.Remove(ctx, p.ID); err != nil {
   295→				m.Logger.Error("cleanup failed", "id", p.ID, "error", err)
   296→			} else {
   297→				removed = append(removed, p.ID)
   298→			}
   299→			continue
   300→		}
   301→
   302→		exists, err := m.branchExists(ctx, app, p.Branch)
   303→		if err != nil {
   304→			m.Logger.Warn("could not check branch, skipping", "id", p.ID, "error", err)
   305→			continue
   306→		}
   307→		if !exists {
   308→			if err := m.Remove(ctx, p.ID); err != nil {
   309→				m.Logger.Error("cleanup failed", "id", p.ID, "error", err)
   310→			} else {
   311→				removed = append(removed, p.ID)
   312→			}
   313→		}
   314→	}
   315→
   316→	if len(removed) > 0 {
   317→		m.Logger.Info("preview cleanup complete", "removed", removed)
   318→	} else {
   319→		m.Logger.Info("preview cleanup: nothing to remove")
   320→	}
   321→	return nil
   322→}
