   342→func (m *PreviewManager) gitSync(ctx context.Context, previewDir string, app config.App, branch string) error {
   343→	repoDir := filepath.Join(previewDir, "repo")
   344→	cloneURL := buildCloneURL(m.Config.Server.GithubToken, app.Repo)
   345→
   346→	_, err := os.Stat(repoDir)
   347→	if os.IsNotExist(err) {
   348→		m.Logger.Info("git clone", "repo", app.Repo, "branch", branch)
   349→		return runCmd(ctx, m.Logger, "", "git",
   350→			"clone", "--branch", branch,
   351→			"--single-branch", "--depth", "1",
   352→			cloneURL, repoDir,
   353→		)
   354→	}
   355→	if err != nil {
   356→		return fmt.Errorf("stat repo dir: %w", err)
   357→	}
   358→
   359→	m.Logger.Info("git fetch+reset", "repo", app.Repo, "branch", branch)
   360→	if err := runCmd(ctx, m.Logger, repoDir, "git", "fetch", "origin", branch); err != nil {
   361→		return err
   362→	}
   363→	return runCmd(ctx, m.Logger, repoDir, "git", "reset", "--hard", "origin/"+branch)
   364→}
