   523→func ensureCaddyNetwork(ctx context.Context, logger *slog.Logger) error {
   524→	cmd := exec.CommandContext(ctx, "docker", "network", "inspect", "caddy")
   525→	if err := cmd.Run(); err == nil {
   526→		return nil
   527→	}
   528→	return runCmd(ctx, logger, "", "docker", "network", "create", "caddy")
   529→}
   530→
   531→func runCmd(ctx context.Context, logger *slog.Logger, dir string, name string, args ...string) error {
   532→	cmd := exec.CommandContext(ctx, name, args...)
   533→	if dir != "" {
   534→		cmd.Dir = dir
   535→	}
   536→
   537→	var stdout, stderr bytes.Buffer
   538→	cmd.Stdout = &stdout
   539→	cmd.Stderr = &stderr
   540→
   541→	start := time.Now()
   542→	runErr := cmd.Run()
   543→	dur := time.Since(start).Round(time.Millisecond)
   544→
   545→	logLines := func(output string, level slog.Level) {
   546→		for line := range strings.Lines(output) {
   547→			line = strings.TrimRight(line, "\n\r")
   548→			if line != "" {
   549→				logger.Log(ctx, level, line, "cmd", name)
   550→			}
   551→		}
   552→	}
   553→
   554→	logLines(stdout.String(), slog.LevelInfo)
   555→	if stderr.Len() > 0 {
   556→		logLines(stderr.String(), slog.LevelWarn)
   557→	}
   558→
   559→	if runErr != nil {
   560→		return fmt.Errorf("%s: %w (duration: %s)", name, runErr, dur)
   561→	}
   562→
   563→	logger.Info("command completed", "cmd", name, "duration", dur)
   564→	return nil
   565→}
