   567→// detectServiceInfo parses a compose file to find the main service name and port.
   568→func detectServiceInfo(composeFilePath, appName string) (serviceName, port string, err error) {
   569→	data, err := os.ReadFile(composeFilePath)
   570→	if err != nil {
   571→		return "", "", err
   572→	}
   573→
   574→	var mc struct {
   575→		Services map[string]struct {
   576→			Expose []any `yaml:"expose"`
   577→			Ports  []any `yaml:"ports"`
   578→		} `yaml:"services"`
   579→	}
   580→	if err := yaml.Unmarshal(data, &mc); err != nil {
   581→		return "", "", err
   582→	}
   583→
   584→	if len(mc.Services) == 0 {
   585→		return "app", "3000", nil
   586→	}
   587→
   588→	names := slices.Sorted(maps.Keys(mc.Services))
   589→	serviceName = names[0]
   590→	for _, n := range names {
   591→		if n == "app" || n == appName {
   592→			serviceName = n
   593→			break
   594→		}
   595→	}
   596→
   597→	svc := mc.Services[serviceName]
   598→	port = extractFirstPort(svc.Expose, svc.Ports)
   599→	if port == "" {
   600→		port = "3000"
   601→	}
   602→	return serviceName, port, nil
   603→}
   604→
   605→func extractFirstPort(expose, ports []any) string {
   606→	for _, v := range expose {
   607→		if p := portFromAny(v); p != "" {
   608→			return p
   609→		}
   610→	}
   611→	for _, v := range ports {
   612→		if p := portFromAny(v); p != "" {
   613→			return p
   614→		}
   615→	}
   616→	return ""
   617→}
   618→
   619→func portFromAny(v any) string {
   620→	switch val := v.(type) {
   621→	case string:
   622→		parts := strings.Split(val, ":")
   623→		return strings.TrimSpace(parts[len(parts)-1])
   624→	case int:
   625→		return fmt.Sprintf("%d", val)
   626→	case map[string]any:
   627→		if t, ok := val["target"]; ok {
   628→			return portFromAny(t)
   629→		}
   630→	}
   631→	return ""
   632→}
   633→
   634→func deepMerge(base, overlay map[string]any) map[string]any {
   635→	result := make(map[string]any, len(base))
   636→	for k, v := range base {
   637→		result[k] = v
   638→	}
   639→	for k, v := range overlay {
   640→		if bv, ok := result[k]; ok {
   641→			if bMap, ok := bv.(map[string]any); ok {
   642→				if oMap, ok := v.(map[string]any); ok {
   643→					result[k] = deepMerge(bMap, oMap)
   644→					continue
   645→				}
   646→			}
   647→		}
   648→		result[k] = v
   649→	}
   650→	return result
   651→}
