    11→// PreviewInfo describes a single active preview deployment.
    12→type PreviewInfo struct {
    13→	ID             string    `json:"id"`
    14→	AppName        string    `json:"app_name"`
    15→	Branch         string    `json:"branch"`
    16→	Domain         string    `json:"domain"`
    17→	Directory      string    `json:"directory"`
    18→	ComposeProject string    `json:"compose_project"`
    19→	ComposeFile    string    `json:"compose_file"`
    20→	CreatedAt      time.Time `json:"created_at"`
    21→	Commit         string    `json:"commit"`
    22→}
    23→
    24→type previewState struct {
    25→	Previews []PreviewInfo `json:"previews"`
    26→}
    27→
    28→func loadState(path string) (*previewState, error) {
    29→	data, err := os.ReadFile(path)
    30→	if os.IsNotExist(err) {
    31→		return &previewState{}, nil
    32→	}
    33→	if err != nil {
    34→		return nil, fmt.Errorf("reading preview state: %w", err)
    35→	}
    36→	var s previewState
    37→	if err := json.Unmarshal(data, &s); err != nil {
    38→		return nil, fmt.Errorf("parsing preview state: %w", err)
    39→	}
    40→	return &s, nil
    41→}
    42→
    43→// saveState writes the state atomically via a temp file + rename.
    44→func saveState(path string, s *previewState) error {
    45→	data, err := json.MarshalIndent(s, "", "  ")
    46→	if err != nil {
    47→		return fmt.Errorf("marshaling preview state: %w", err)
    48→	}
    49→	tmp := path + ".tmp"
    50→	if err := os.WriteFile(tmp, data, 0644); err != nil {
    51→		return fmt.Errorf("writing preview state: %w", err)
    52→	}
    53→	if err := os.Rename(tmp, path); err != nil {
    54→		os.Remove(tmp) //nolint:errcheck
    55→		return fmt.Errorf("renaming preview state: %w", err)
    56→	}
    57→	return nil
    58→}
    59→
    60→func statePath(dataDir string) string {
    61→	return filepath.Join(dataDir, "previews.json")
    62→}
