   215→// List returns all active previews.
   216→func (m *PreviewManager) List() ([]PreviewInfo, error) {
   217→	m.mu.Lock()
   218→	defer m.mu.Unlock()
   219→	state, err := loadState(statePath(m.DataDir))
   220→	if err != nil {
   221→		return nil, err
   222→	}
   223→	return state.Previews, nil
