   226→// Remove tears down the preview with the given ID.
   227→func (m *PreviewManager) Remove(ctx context.Context, previewID string) error {
   228→	m.mu.Lock()
   229→	state, err := loadState(statePath(m.DataDir))
   230→	if err != nil {
   231→		m.mu.Unlock()
   232→		return err
   233→	}
   234→
   235→	var found *PreviewInfo
   236→	for _, p := range state.Previews {
   237→		if p.ID == previewID {
   238→			pp := p
   239→			found = &pp
   240→			break
   241→		}
   242→	}
   243→	m.mu.Unlock()
   244→
   245→	if found == nil {
   246→		return fmt.Errorf("preview %q not found", previewID)
   247→	}
   248→
   249→	if err := m.runComposeDown(ctx, found.Directory, found.ComposeProject, found.ComposeFile); err != nil {
   250→		m.Logger.Warn("compose down failed", "id", previewID, "error", err)
   251→	}
   252→
   253→	// Prune images tagged with this preview.
   254→	pruneCmd := exec.CommandContext(ctx, "docker", "image", "prune", "-f",
   255→		"--filter", "label=com.herald.preview="+previewID)
   256→	_ = pruneCmd.Run()
   257→
   258→	if err := os.RemoveAll(found.Directory); err != nil {
   259→		m.Logger.Warn("removing preview dir failed", "id", previewID, "error", err)
   260→	}
   261→
   262→	m.mu.Lock()
   263→	defer m.mu.Unlock()
   264→
   265→	state, err = loadState(statePath(m.DataDir))
   266→	if err != nil {
   267→		return fmt.Errorf("reloading state: %w", err)
   268→	}
   269→	state.Previews = slices.DeleteFunc(state.Previews, func(p PreviewInfo) bool {
   270→		return p.ID == previewID
   271→	})
   272→	if err := saveState(statePath(m.DataDir), state); err != nil {
   273→		return fmt.Errorf("saving state: %w", err)
   274→	}
   275→
   276→	m.Logger.Info("preview removed", "id", previewID)
   277→	return nil
   278→}
