   329→// branchExists checks whether the branch exists on the remote.
   330→func (m *PreviewManager) branchExists(ctx context.Context, app config.App, branch string) (bool, error) {
   331→	cloneURL := buildCloneURL(m.Config.Server.GithubToken, app.Repo)
   332→	cmd := exec.CommandContext(ctx, "git", "ls-remote", "--heads", cloneURL, branch)
   333→	out, err := cmd.Output()
   334→	if err != nil {
   335→		return false, err
   336→	}
   337→	return len(strings.TrimSpace(string(out))) > 0, nil
   338→}
