   392→// --- Compose override generation ---
   393→
   394→type composeOverride struct {
   395→	Services map[string]serviceOverride `yaml:"services"`
   396→	Networks map[string]networkDef      `yaml:"networks,omitempty"`
   397→	Secrets  map[string]secretFileDef   `yaml:"secrets,omitempty"`
   398→}
   399→
   400→type serviceOverride struct {
   401→	Labels   map[string]string `yaml:"labels,omitempty"`
   402→	EnvFile  []string          `yaml:"env_file,omitempty"`
   403→	Secrets  []string          `yaml:"secrets,omitempty"`
   404→	Networks []string          `yaml:"networks,omitempty"`
   405→}
   406→
   407→type networkDef struct {
   408→	External bool `yaml:"external"`
   409→}
   410→
   411→type secretFileDef struct {
   412→	File string `yaml:"file"`
   413→}
   414→
   415→func (m *PreviewManager) generateOverride(
   416→	root *os.Root,
   417→	previewDir, appName, previewID, domain string,
   418→	app config.App,
   419→	repoDir string,
   420→	dockerSecrets map[string]string,
   421→) error {
   422→	serviceName, port, err := detectServiceInfo(filepath.Join(repoDir, app.Compose), appName)
   423→	if err != nil {
   424→		m.Logger.Warn("could not detect service info, using defaults", "app", appName, "error", err)
   425→		serviceName = "app"
   426→		port = "3000"
   427→	}
   428→
   429→	svc := serviceOverride{
   430→		Labels: map[string]string{
   431→			"caddy":               domain,
   432→			"caddy.reverse_proxy": fmt.Sprintf("{{upstreams %s}}", port),
   433→			"com.herald.preview":  previewID,
   434→		},
   435→		Networks: []string{"caddy"},
   436→	}
   437→
   438→	if app.EnvFile != "" {
   439→		svc.EnvFile = []string{app.EnvFile}
   440→	}
   441→
   442→	secretNames := slices.Sorted(maps.Keys(dockerSecrets))
   443→	if len(secretNames) > 0 {
   444→		svc.Secrets = secretNames
   445→	}
   446→
   447→	override := composeOverride{
   448→		Services: map[string]serviceOverride{serviceName: svc},
   449→		Networks: map[string]networkDef{"caddy": {External: true}},
   450→	}
   451→
   452→	if len(secretNames) > 0 {
   453→		override.Secrets = make(map[string]secretFileDef, len(secretNames))
   454→		for _, name := range secretNames {
   455→			override.Secrets[name] = secretFileDef{
   456→				File: filepath.Join(previewDir, "secrets", name),
   457→			}
   458→		}
   459→	}
   460→
   461→	data, err := yaml.Marshal(override)
   462→	if err != nil {
   463→		return fmt.Errorf("marshaling override: %w", err)
   464→	}
   465→
   466→	if app.Override != "" {
   467→		var baseMap, overlayMap map[string]any
   468→		if err := yaml.Unmarshal(data, &baseMap); err != nil {
   469→			return fmt.Errorf("re-parsing generated override: %w", err)
   470→		}
   471→		if err := yaml.Unmarshal([]byte(app.Override), &overlayMap); err != nil {
   472→			return fmt.Errorf("parsing app override YAML: %w", err)
   473→		}
   474→		merged := deepMerge(baseMap, overlayMap)
   475→		data, err = yaml.Marshal(merged)
   476→		if err != nil {
   477→			return fmt.Errorf("marshaling merged override: %w", err)
   478→		}
   479→	}
   480→
   481→	f, err := root.OpenFile("compose.override.yml", os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0644)
   482→	if err != nil {
   483→		return err
   484→	}
   485→	defer f.Close()
   486→	_, err = f.Write(data)
   487→	return err
   488→}
