   492→func buildCloneURL(token, repo string) string {
   493→	if token != "" {
   494→		return fmt.Sprintf("https://%s@github.com/%s.git", token, repo)
   495→	}
   496→	return fmt.Sprintf("https://github.com/%s.git", repo)
