   499→func writeEnvFile(root *os.Root, envVars map[string]string) error {
   500→	f, err := root.OpenFile(".env", os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0600)
   501→	if err != nil {
   502→		return err
   503→	}
   504→	defer f.Close()
   505→	for _, key := range slices.Sorted(maps.Keys(envVars)) {
   506→		if _, err := fmt.Fprintf(f, "%s=%s\n", key, envVars[key]); err != nil {
   507→			return err
   508→		}
   509→	}
   510→	return nil
   511→}
