   513→func writeSecret(root *os.Root, name, value string) error {
   514→	f, err := root.OpenFile(name, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0600)
   515→	if err != nil {
   516→		return err
   517→	}
   518→	defer f.Close()
   519→	_, err = f.WriteString(value)
   520→	return err
   521→}
