package preview

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"time"
)

// PreviewInfo describes a single active preview deployment.
type PreviewInfo struct {
	ID             string    `json:"id"`
	AppName        string    `json:"app_name"`
	Branch         string    `json:"branch"`
	Domain         string    `json:"domain"`
	Directory      string    `json:"directory"`
	ComposeProject string    `json:"compose_project"`
	ComposeFile    string    `json:"compose_file"`
	CreatedAt      time.Time `json:"created_at"`
	Commit         string    `json:"commit"`
}

type previewState struct {
	Previews []PreviewInfo `json:"previews"`
}

func loadState(path string) (*previewState, error) {
	data, err := os.ReadFile(path)
	if os.IsNotExist(err) {
		return &previewState{}, nil
	}
	if err != nil {
		return nil, fmt.Errorf("reading preview state: %w", err)
	}
	var s previewState
	if err := json.Unmarshal(data, &s); err != nil {
		return nil, fmt.Errorf("parsing preview state: %w", err)
	}
	return &s, nil
}

// saveState writes the state atomically via a temp file + rename.
func saveState(path string, s *previewState) error {
	data, err := json.MarshalIndent(s, "", "  ")
	if err != nil {
		return fmt.Errorf("marshaling preview state: %w", err)
	}
	tmp := path + ".tmp"
	if err := os.WriteFile(tmp, data, 0644); err != nil {
		return fmt.Errorf("writing preview state: %w", err)
	}
	if err := os.Rename(tmp, path); err != nil {
		os.Remove(tmp) //nolint:errcheck
		return fmt.Errorf("renaming preview state: %w", err)
	}
	return nil
}

func statePath(dataDir string) string {
	return filepath.Join(dataDir, "previews.json")
}

package cmd

import (
	"os"
	"path/filepath"

	"github.com/nogo/herald/internal/config"
	"github.com/spf13/cobra"
)

var (
	cfgFile string
	verbose bool
	dataDir string

	// Cfg holds the loaded config, accessible to all subcommands.
	Cfg *config.Config
)

// skipConfigCommands are commands that run without a config file.
var skipConfigCommands = map[string]bool{
	"version": true,
	"init":    true,
}

var rootCmd = &cobra.Command{
	Use:   "herald",
	Short: "herald — deploy daemon for self-hosted infrastructure",
	PersistentPreRunE: func(cmd *cobra.Command, args []string) error {
		if skipConfigCommands[cmd.Name()] {
			return nil
		}

		// Auto-detect config from <data-dir>/repo/config.yml if --config was not
		// explicitly provided and the default path doesn't exist.
		if !cmd.Flags().Changed("config") {
			autoPath := filepath.Join(filepath.Clean(dataDir), "repo", "config.yml")
			if _, err := os.Stat(autoPath); err == nil {
				cfgFile = autoPath
			}
		}

		cfg, err := config.Load(cfgFile)
		if err != nil {
			return err
		}
		Cfg = cfg
		return nil
	},
}

func Execute() {
	if err := rootCmd.Execute(); err != nil {
		os.Exit(1)
	}
}

func init() {
	rootCmd.PersistentFlags().StringVarP(&cfgFile, "config", "c", "/etc/herald/config.yml", "Path to config file")
	rootCmd.PersistentFlags().BoolVarP(&verbose, "verbose", "v", false, "Enable verbose output")
	rootCmd.PersistentFlags().StringVar(&dataDir, "data-dir", "/etc/herald/", "Directory for age key and secrets file")
}

package cmd

import (
	"context"
	"fmt"
	"log/slog"
	"os"
	"text/tabwriter"

	"github.com/nogo/herald/internal/github"
	"github.com/nogo/herald/internal/secrets"
	"github.com/spf13/cobra"
)

var webhooksCmd = &cobra.Command{
	Use:   "webhooks",
	Short: "Manage GitHub webhooks",
	Run: func(cmd *cobra.Command, args []string) {
		cmd.Help()
	},
}

var webhooksSyncCmd = &cobra.Command{
	Use:   "sync",
	Short: "Register missing webhooks and remove stale ones",
	Args:  cobra.NoArgs,
	RunE: func(cmd *cobra.Command, args []string) error {
		if Cfg.Server.GithubToken == "" {
			fmt.Fprintln(os.Stderr, "GitHub token not configured. Set GITHUB_TOKEN environment variable.")
			os.Exit(1)
		}

		store := secrets.NewStore(dataDir)
		client := github.NewGitHubClient(Cfg.Server.GithubToken, slog.Default())

		results, err := github.SyncWebhooks(context.Background(), Cfg, store, client)
		if err != nil {
			return err
		}

		fmt.Fprintln(cmd.OutOrStdout(), "Webhooks synced:")
		for _, r := range results {
			switch r.Action {
			case "exists":
				fmt.Fprintf(cmd.OutOrStdout(), "  %-30s ✓ exists (id: %d)\n", r.Repo, r.ID)
			case "created":
				fmt.Fprintf(cmd.OutOrStdout(), "  %-30s + created (id: %d)\n", r.Repo, r.ID)
			case "removed":
				fmt.Fprintf(cmd.OutOrStdout(), "  %-30s - removed (id: %d)\n", r.Repo, r.ID)
			case "error":
				fmt.Fprintf(cmd.OutOrStdout(), "  %-30s ! error: %v\n", r.Repo, r.Error)
			}
		}

		return nil
	},
}

var webhooksListCmd = &cobra.Command{
	Use:   "list",
	Short: "List webhook status for all repos in config",
	Args:  cobra.NoArgs,
	RunE: func(cmd *cobra.Command, args []string) error {
		if Cfg.Server.GithubToken == "" {
			fmt.Fprintln(os.Stderr, "GitHub token not configured. Set GITHUB_TOKEN environment variable.")
			os.Exit(1)
		}

		client := github.NewGitHubClient(Cfg.Server.GithubToken, slog.Default())
		statuses := github.ListWebhookStatuses(context.Background(), Cfg, client)

		w := tabwriter.NewWriter(cmd.OutOrStdout(), 0, 0, 3, ' ', 0)
		fmt.Fprintln(w, "Repo\tWebhook URL\tStatus")
		for _, s := range statuses {
			if s.Found {
				status := "active"
				if !s.Active {
					status = "inactive"
				}
				fmt.Fprintf(w, "%s\t%s\t%s\n", s.Repo, s.URL, status)
			} else {
				fmt.Fprintf(w, "%s\t%s\t%s\n", s.Repo, "-", "not registered")
			}
		}
		w.Flush()

		return nil
	},
}

func init() {
	webhooksCmd.AddCommand(webhooksSyncCmd, webhooksListCmd)
	rootCmd.AddCommand(webhooksCmd)
}

