	"github.com/nogo/herald/internal/caddy"
	"github.com/nogo/herald/internal/preview"
	"github.com/nogo/herald/internal/status"
	"github.com/spf13/cobra"
)

var statusJSON bool

var statusCmd = &cobra.Command{
	Use:   "status",
	Short: "Show all services, domains, and health",
	RunE: func(cmd *cobra.Command, args []string) error {
		cmd.SilenceUsage = true

		caddyMgr := &caddy.CaddyManager{
			Config:     Cfg,
			Logger:     slog.Default(),
			HeraldPort: port,
		}

		previewMgr := &preview.PreviewManager{
			Config:  Cfg,
			DataDir: dataDir,
			Logger:  slog.Default(),
		}

		collector := &status.StatusCollector{
			Config:  Cfg,
			DataDir: dataDir,
			Logger:  slog.Default(),
			Caddy:   caddyMgr,
			Preview: previewMgr,
		}

		ctx := context.Background()
		s, err := collector.Collect(ctx)
		if err != nil {
			return err
		}

		if statusJSON {
			data, err := json.MarshalIndent(s, "", "  ")
			if err != nil {
				return err
			}
			fmt.Fprintln(cmd.OutOrStdout(), string(data))
			return nil
		}

		printStatus(cmd.OutOrStdout(), s)
		return nil
	},
}

func stateIcon(state string) string {
	switch state {
	case "running":
		return "● running"
	case "degraded":
		return "◐ degraded"
	case "stopped":
		return "○ stopped"
	case "not deployed":
		return "○ not deployed"
	case "error":
		return "✗ error"
	default:
		return "? " + state
	}
}

